{
  "findings": [
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket has an ACL defined which allows public READ access",
      "resource": "aws_s3_bucket.logs",
      "severity": "CRITICAL",
      "explanation": "The ACL 'log-delivery-write' allows public WRITE access, not just READ, but it's still a non-private ACL that could potentially expose the bucket to unintended access."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration, which could lead to unmanaged storage costs and data retention issues."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "private"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "logs_lifecycle" {
  bucket = aws_s3_bucket.logs.id
  rule {
    id     = "logs-lifecycle-rule"
    status = "Enabled"
    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}",
  "fix_summary": "Changed the S3 bucket ACL to 'private' to prevent potential public access and added a lifecycle configuration to manage the bucket's objects."
}
